		}
		this._right = right;
		this.domNode.style.right = this._right;
	}
	public setPaddingTop(_paddingTop: number | string): void {
		const paddingTop = numberAsPixels(_paddingTop);

		if (this._paddingTop === paddingTop) {
			return;
