export interface MarkedOptions extends marked.MarkedOptions {
	baseUrl?: never;
}

export interface MarkdownRenderOptions extends FormattedTextRenderOptions {
	readonly codeBlockRenderer?: (
		languageId: string,
		value: string,
	) => Promise<HTMLElement>;
	readonly codeBlockRendererSync?: (
		languageId: string,
		value: string,
		raw?: string,
	) => HTMLElement;
	readonly asyncRenderCallback?: () => void;
	readonly fillInIncompleteTokens?: boolean;
	readonly remoteImageIsAllowed?: (uri: URI) => boolean;
	readonly sanitizerOptions?: ISanitizerOptions;
}

export interface ISanitizerOptions {
	replaceWithPlaintext?: boolean;
	allowedTags?: string[];
}

const defaultMarkedRenderers = Object.freeze({
	image: ({ href, title, text }: marked.Tokens.Image): string => {
		let dimensions: string[] = [];

		let attributes: string[] = [];

		if (href) {
			({ href, dimensions } = parseHrefAndDimensions(href));
			attributes.push(`src="${escapeDoubleQuotes(href)}"`);
		}
		if (text) {
			attributes.push(`alt="${escapeDoubleQuotes(text)}"`);
		}
		if (title) {
			attributes.push(`title="${escapeDoubleQuotes(title)}"`);
		}
		if (dimensions.length) {
			attributes = attributes.concat(dimensions);
		}
		return "<img " + attributes.join(" ") + ">";
	},

	paragraph(
		this: marked.Renderer,
		{ tokens }: marked.Tokens.Paragraph,
	): string {
		return `<p>${this.parser.parseInline(tokens)}</p>`;
	},

	link(
		this: marked.Renderer,
		{ href, title, tokens }: marked.Tokens.Link,
	): string {
		let text = this.parser.parseInline(tokens);

		if (typeof href !== "string") {
			return "";
		}

		// Remove markdown escapes. Workaround for https://github.com/chjj/marked/issues/829
		if (href === text) {
			// raw link case
			text = removeMarkdownEscapes(text);
		}

		title =
			typeof title === "string"
				? escapeDoubleQuotes(removeMarkdownEscapes(title))
				: "";
		href = removeMarkdownEscapes(href);

		// HTML Encode href
		href = href
			.replace(/&/g, "&amp;")
			.replace(/</g, "&lt;")
			.replace(/>/g, "&gt;")
			.replace(/"/g, "&quot;")
			.replace(/'/g, "&#39;");

		return `<a href="${href}" title="${title || href}" draggable="false">${text}</a>`;
	},
});

/**
 * Low-level way create a html element from a markdown string.
 *
 * **Note** that for most cases you should be using {@link import('../../editor/browser/widget/markdownRenderer/browser/markdownRenderer.js').MarkdownRenderer MarkdownRenderer}
 * which comes with support for pretty code block rendering and which uses the default way of handling links.
 */
export function renderMarkdown(
	markdown: IMarkdownString,
	options: MarkdownRenderOptions = {},
	markedOptions: Readonly<MarkedOptions> = {},
): { element: HTMLElement; dispose: () => void } {
	const disposables = new DisposableStore();

	let isDisposed = false;

	const element = createElement(options);

	const { renderer, codeBlocks, syncCodeBlocks } = createMarkdownRenderer(
		options,
		markdown,
	);

	const value = preprocessMarkdownString(markdown);

	let renderedMarkdown: string;

	if (options.fillInIncompleteTokens) {
		// The defaults are applied by parse but not lexer()/parser(), and they need to be present
		const opts: MarkedOptions = {
			...marked.defaults,
			...markedOptions,
			renderer,
		};

		const tokens = marked.lexer(value, opts);

		const newTokens = fillInIncompleteTokens(tokens);
		renderedMarkdown = marked.parser(newTokens, opts);
	} else {
		renderedMarkdown = marked.parse(value, {
			...markedOptions,
			renderer,
			async: false,
		});
	}

	// Rewrite theme icons
	if (markdown.supportThemeIcons) {
		const elements = renderLabelWithIcons(renderedMarkdown);
		renderedMarkdown = elements
			.map((e) => (typeof e === "string" ? e : e.outerHTML))
			.join("");
	}

	const htmlParser = new DOMParser();

	const markdownHtmlDoc = htmlParser.parseFromString(
		sanitizeRenderedMarkdown(
			{ isTrusted: markdown.isTrusted, ...options.sanitizerOptions },
			renderedMarkdown,
		) as unknown as string,
		"text/html",
	);

	rewriteRenderedLinks(markdown, options, markdownHtmlDoc.body);

	element.innerHTML = sanitizeRenderedMarkdown(
		{ isTrusted: markdown.isTrusted, ...options.sanitizerOptions },
		markdownHtmlDoc.body.innerHTML,
	) as unknown as string;

	if (codeBlocks.length > 0) {
		Promise.all(codeBlocks).then((tuples) => {
			if (isDisposed) {
				return;
			}
			const renderedElements = new Map(tuples);

			const placeholderElements =
				element.querySelectorAll<HTMLDivElement>(`div[data-code]`);

			for (const placeholderElement of placeholderElements) {
				const renderedElement = renderedElements.get(
					placeholderElement.dataset["code"] ?? "",
				);

				if (renderedElement) {
					DOM.reset(placeholderElement, renderedElement);
				}
			}
			options.asyncRenderCallback?.();
		});
	} else if (syncCodeBlocks.length > 0) {
		const renderedElements = new Map(syncCodeBlocks);

		const placeholderElements =
			element.querySelectorAll<HTMLDivElement>(`div[data-code]`);

		for (const placeholderElement of placeholderElements) {
			const renderedElement = renderedElements.get(
				placeholderElement.dataset["code"] ?? "",
			);

			if (renderedElement) {
				DOM.reset(placeholderElement, renderedElement);
			}
		}
	}

	// Signal size changes for image tags
	if (options.asyncRenderCallback) {
		for (const img of element.getElementsByTagName("img")) {
			const listener = disposables.add(
				DOM.addDisposableListener(img, "load", () => {
					listener.dispose();
					options.asyncRenderCallback!();
				}),
			);
		}
	}

	// Add event listeners for links
	if (options.actionHandler) {
		const onClick = options.actionHandler.disposables.add(
			new DomEmitter(element, "click"),
		);

		const onAuxClick = options.actionHandler.disposables.add(
			new DomEmitter(element, "auxclick"),
		);
		options.actionHandler.disposables.add(
			Event.any(
				onClick.event,
				onAuxClick.event,
			)((e) => {
				const mouseEvent = new StandardMouseEvent(
					DOM.getWindow(element),
					e,
				);

				if (!mouseEvent.leftButton && !mouseEvent.middleButton) {
					return;
				}
				activateLink(markdown, options, mouseEvent);
			}),
		);

		options.actionHandler.disposables.add(
			DOM.addDisposableListener(element, "keydown", (e) => {
				const keyboardEvent = new StandardKeyboardEvent(e);

				if (
					!keyboardEvent.equals(KeyCode.Space) &&
					!keyboardEvent.equals(KeyCode.Enter)
				) {
					return;
				}
				activateLink(markdown, options, keyboardEvent);
			}),
		);
	}

	return {
		element,
		dispose: () => {
			isDisposed = true;
			disposables.dispose();
		},
	};
}

function rewriteRenderedLinks(
	markdown: IMarkdownString,
	options: MarkdownRenderOptions,
	root: HTMLElement,
) {
	for (const el of root.querySelectorAll("img, audio, video, source")) {
		const src = el.getAttribute("src"); // Get the raw 'src' attribute value as text, not the resolved 'src'
		if (src) {
			let href = src;

			try {
				if (markdown.baseUri) {
					// absolute or relative local path, or file: uri
					href = resolveWithBaseUri(URI.from(markdown.baseUri), href);
				}
			} catch (err) {}

			el.setAttribute("src", massageHref(markdown, href, true));

			if (options.remoteImageIsAllowed) {
				const uri = URI.parse(href);

				if (
					uri.scheme !== Schemas.file &&
					uri.scheme !== Schemas.data &&
					!options.remoteImageIsAllowed(uri)
				) {
					el.replaceWith(DOM.$("", undefined, el.outerHTML));
				}
			}
		}
	}

	for (const el of root.querySelectorAll("a")) {
		const href = el.getAttribute("href"); // Get the raw 'href' attribute value as text, not the resolved 'href'
		el.setAttribute("href", ""); // Clear out href. We use the `data-href` for handling clicks instead
		if (
			!href ||
			/^data:|javascript:/i.test(href) ||
			(/^command:/i.test(href) && !markdown.isTrusted) ||
			/^command:(\/\/\/)?_workbench\.downloadResource/i.test(href)
		) {
			// drop the link
			el.replaceWith(...el.childNodes);
		} else {
			let resolvedHref = massageHref(markdown, href, false);

			if (markdown.baseUri) {
				resolvedHref = resolveWithBaseUri(
					URI.from(markdown.baseUri),
					href,
				);
			}
			el.dataset.href = resolvedHref;
		}
	}
}

function createMarkdownRenderer(
	options: MarkdownRenderOptions,
	markdown: IMarkdownString,
): {
	renderer: marked.Renderer;
	codeBlocks: Promise<[string, HTMLElement]>[];
	syncCodeBlocks: [string, HTMLElement][];
} {
	const renderer = new marked.Renderer();
	renderer.image = defaultMarkedRenderers.image;
	renderer.link = defaultMarkedRenderers.link;
	renderer.paragraph = defaultMarkedRenderers.paragraph;

	// Will collect [id, renderedElement] tuples
	const codeBlocks: Promise<[string, HTMLElement]>[] = [];

	const syncCodeBlocks: [string, HTMLElement][] = [];

	if (options.codeBlockRendererSync) {
		renderer.code = ({ text, lang, raw }: marked.Tokens.Code) => {
			const id = defaultGenerator.nextId();

			const value = options.codeBlockRendererSync!(
				postProcessCodeBlockLanguageId(lang),
				text,
				raw,
			);
			syncCodeBlocks.push([id, value]);

			return `<div class="code" data-code="${id}">${escape(text)}</div>`;
		};
	} else if (options.codeBlockRenderer) {
		renderer.code = ({ text, lang }: marked.Tokens.Code) => {
			const id = defaultGenerator.nextId();

			const value = options.codeBlockRenderer!(
				postProcessCodeBlockLanguageId(lang),
				text,
			);
			codeBlocks.push(value.then((element) => [id, element]));

			return `<div class="code" data-code="${id}">${escape(text)}</div>`;
		};
	}

	if (!markdown.supportHtml) {
		// Note: we always pass the output through dompurify after this so that we don't rely on
		// marked for real sanitization.
		renderer.html = ({ text }) => {
			if (options.sanitizerOptions?.replaceWithPlaintext) {
				return escape(text);
			}

			const match = markdown.isTrusted
				? text.match(/^(<span[^>]+>)|(<\/\s*span>)$/)
				: undefined;

			return match ? text : "";
		};
	}
	return { renderer, codeBlocks, syncCodeBlocks };
}

function preprocessMarkdownString(markdown: IMarkdownString) {
	let value = markdown.value;

	// values that are too long will freeze the UI
	if (value.length > 100_000) {
		value = `${value.substr(0, 100_000)}…`;
	}

	// escape theme icons
	if (markdown.supportThemeIcons) {
		value = markdownEscapeEscapedIcons(value);
	}

	return value;
}

function activateLink(
	markdown: IMarkdownString,
	options: MarkdownRenderOptions,
	event: StandardMouseEvent | StandardKeyboardEvent,
): void {
	const target = event.target.closest("a[data-href]");

	if (!DOM.isHTMLElement(target)) {
		return;
	}

	try {
		let href = target.dataset["href"];

		if (href) {
			if (markdown.baseUri) {
				href = resolveWithBaseUri(URI.from(markdown.baseUri), href);
			}
			options.actionHandler!.callback(href, event);
		}
	} catch (err) {
		onUnexpectedError(err);
	} finally {
		event.preventDefault();
	}
}

function uriMassage(markdown: IMarkdownString, part: string): string {
	let data: any;

	try {
		data = parse(decodeURIComponent(part));
	} catch (e) {
		// ignore
	}
	if (!data) {
		return part;
	}
	data = cloneAndChange(data, (value) => {
		if (markdown.uris && markdown.uris[value]) {
			return URI.revive(markdown.uris[value]);
		} else {
			return undefined;
		}
	});

	return encodeURIComponent(JSON.stringify(data));
}

function massageHref(
	markdown: IMarkdownString,
	href: string,
	isDomUri: boolean,
): string {
	const data = markdown.uris && markdown.uris[href];

	let uri = URI.revive(data);

	if (isDomUri) {
		if (href.startsWith(Schemas.data + ":")) {
			return href;
		}
		if (!uri) {
			uri = URI.parse(href);
		}
		// this URI will end up as "src"-attribute of a dom node
		// and because of that special rewriting needs to be done
		// so that the URI uses a protocol that's understood by
		// browsers (like http or https)
		return FileAccess.uriToBrowserUri(uri).toString(true);
	}
	if (!uri) {
		return href;
	}
	if (URI.parse(href).toString() === uri.toString()) {
		return href; // no transformation performed
	}
	if (uri.query) {
		uri = uri.with({ query: uriMassage(markdown, uri.query) });
	}
	return uri.toString();
}

function postProcessCodeBlockLanguageId(lang: string | undefined): string {
	if (!lang) {
		return "";
	}

	const parts = lang.split(/[\s+|:|,|\{|\?]/, 1);

	if (parts.length) {
		return parts[0];
	}
	return lang;
}

function resolveWithBaseUri(baseUri: URI, href: string): string {
	const hasScheme = /^\w[\w\d+.-]*:/.test(href);

	if (hasScheme) {
		return href;
	}

	if (baseUri.path.endsWith("/")) {
		return resolvePath(baseUri, href).toString();
	} else {
		return resolvePath(dirname(baseUri), href).toString();
	}
}

interface IInternalSanitizerOptions extends ISanitizerOptions {
	isTrusted?: boolean | MarkdownStringTrustedOptions;
}

const selfClosingTags = [
	"area",
	"base",
	"br",
	"col",
	"command",
	"embed",
	"hr",
	"img",
	"input",
	"keygen",
	"link",
	"meta",
	"param",
	"source",
	"track",
	"wbr",
];

function sanitizeRenderedMarkdown(
	options: IInternalSanitizerOptions,
	renderedMarkdown: string,
): TrustedHTML {
	const { config, allowedSchemes } = getSanitizerOptions(options);

	const store = new DisposableStore();
	store.add(
		addDompurifyHook("uponSanitizeAttribute", (element, e) => {
			if (e.attrName === "style" || e.attrName === "class") {
				if (element.tagName === "SPAN") {
					if (e.attrName === "style") {
						e.keepAttr =
							/^(color\:(#[0-9a-fA-F]+|var\(--vscode(-[a-zA-Z0-9]+)+\));)?(background-color\:(#[0-9a-fA-F]+|var\(--vscode(-[a-zA-Z0-9]+)+\));)?(border-radius:[0-9]+px;)?$/.test(
								e.attrValue,
							);

						return;
					} else if (e.attrName === "class") {
						e.keepAttr =
							/^codicon codicon-[a-z\-]+( codicon-modifier-[a-z\-]+)?$/.test(
