import {
	Action,
	ActionRunner,
	IAction,
	IActionChangeEvent,
	IActionRunner,
	Separator,
} from "../../../common/actions.js";
import { Disposable } from "../../../common/lifecycle.js";
import * as platform from "../../../common/platform.js";
import * as types from "../../../common/types.js";
import { isFirefox } from "../../browser.js";
import { DataTransfers } from "../../dnd.js";
import {
	addDisposableListener,
	EventHelper,
	EventLike,
	EventType,
} from "../../dom.js";
import { Gesture, EventType as TouchEventType } from "../../touch.js";
import { IContextViewProvider } from "../contextview/contextview.js";
import { IHoverDelegate } from "../hover/hoverDelegate.js";
import { getDefaultHoverDelegate } from "../hover/hoverDelegateFactory.js";
import {
	ISelectBoxOptions,
	ISelectBoxStyles,
	ISelectOptionItem,
	SelectBox,
} from "../selectBox/selectBox.js";
import { IToggleStyles } from "../toggle/toggle.js";
import { IActionViewItem } from "./actionbar.js";

import "./actionbar.css";

import * as nls from "../../../../nls.js";
import type { IManagedHover } from "../hover/hover.js";
import { getBaseLayerHoverDelegate } from "../hover/hoverDelegate2.js";

export interface IBaseActionViewItemOptions {
	draggable?: boolean;
	isMenu?: boolean;
	isTabList?: boolean;
	useEventAsContext?: boolean;
	hoverDelegate?: IHoverDelegate;
}

export class BaseActionViewItem extends Disposable implements IActionViewItem {
	element: HTMLElement | undefined;

	_context: unknown;
	readonly _action: IAction;

	private customHover?: IManagedHover;

	get action() {
		return this._action;
	}

	private _actionRunner: IActionRunner | undefined;

	constructor(
		context: unknown,
		action: IAction,
		protected options: IBaseActionViewItemOptions = {},
	) {
		super();

		this._context = context || this;
		this._action = action;

		if (action instanceof Action) {
			this._register(
				action.onDidChange((event) => {
					if (!this.element) {
						// we have not been rendered yet, so there
						// is no point in updating the UI
						return;
					}

					this.handleActionChangeEvent(event);
				}),
			);
		}
	}

	private handleActionChangeEvent(event: IActionChangeEvent): void {
		if (event.enabled !== undefined) {
			this.updateEnabled();
		}

		if (event.checked !== undefined) {
			this.updateChecked();
		}

		if (event.class !== undefined) {
			this.updateClass();
		}

		if (event.label !== undefined) {
			this.updateLabel();
			this.updateTooltip();
		}

		if (event.tooltip !== undefined) {
			this.updateTooltip();
		}
	}

	get actionRunner(): IActionRunner {
		if (!this._actionRunner) {
			this._actionRunner = this._register(new ActionRunner());
		}

		return this._actionRunner;
	}

	set actionRunner(actionRunner: IActionRunner) {
		this._actionRunner = actionRunner;
	}

	isEnabled(): boolean {
		return this._action.enabled;
	}

	setActionContext(newContext: unknown): void {
		this._context = newContext;
	}

	render(container: HTMLElement): void {
		const element = (this.element = container);
		this._register(Gesture.addTarget(container));

		const enableDragging = this.options && this.options.draggable;

		if (enableDragging) {
			container.draggable = true;

			if (isFirefox) {
				// Firefox: requires to set a text data transfer to get going
				this._register(
					addDisposableListener(
						container,
						EventType.DRAG_START,
						(e) =>
							e.dataTransfer?.setData(
								DataTransfers.TEXT,
								this._action.label,
							),
					),
				);
			}
		}

		this._register(
			addDisposableListener(element, TouchEventType.Tap, (e) =>
				this.onClick(e, true),
			),
		); // Preserve focus on tap #125470

		this._register(
