export interface IActionViewItemOptions extends IBaseActionViewItemOptions {
	icon?: boolean;
	label?: boolean;
	keybinding?: string | null;
	keybindingNotRenderedWithLabel?: boolean;
	toggleStyles?: IToggleStyles;
}

export class ActionViewItem extends BaseActionViewItem {
	protected label: HTMLElement | undefined;
	protected override options: IActionViewItemOptions;

	private cssClass?: string;

	constructor(
		context: unknown,
		action: IAction,
		options: IActionViewItemOptions,
	) {
		super(context, action, options);

		this.options = options;
		this.options.icon = options.icon !== undefined ? options.icon : false;
		this.options.label = options.label !== undefined ? options.label : true;
		this.cssClass = "";
	}

	override render(container: HTMLElement): void {
		super.render(container);
		types.assertType(this.element);

		const label = document.createElement("a");
		label.classList.add("action-label");
		label.setAttribute("role", this.getDefaultAriaRole());

		this.label = label;
		this.element.appendChild(label);

		if (
			this.options.label &&
			this.options.keybinding &&
			!this.options.keybindingNotRenderedWithLabel
		) {
			const kbLabel = document.createElement("span");
			kbLabel.classList.add("keybinding");
			kbLabel.textContent = this.options.keybinding;
			this.element.appendChild(kbLabel);
		}

		this.updateClass();
		this.updateLabel();
		this.updateTooltip();
		this.updateEnabled();
		this.updateChecked();
	}

	private getDefaultAriaRole():
		| "presentation"
		| "menuitem"
		| "tab"
		| "button" {
		if (this._action.id === Separator.ID) {
			return "presentation"; // A separator is a presentation item
		} else {
			if (this.options.isMenu) {
				return "menuitem";
			} else if (this.options.isTabList) {
				return "tab";
			} else {
				return "button";
			}
		}
	}

	// Only set the tabIndex on the element once it is about to get focused
	// That way this element wont be a tab stop when it is not needed #106441
	override focus(): void {
		if (this.label) {
			this.label.tabIndex = 0;
			this.label.focus();
		}
	}

	override isFocused(): boolean {
		return !!this.label && this.label?.tabIndex === 0;
	}

	override blur(): void {
		if (this.label) {
			this.label.tabIndex = -1;
		}
	}

	override setFocusable(focusable: boolean): void {
		if (this.label) {
			this.label.tabIndex = focusable ? 0 : -1;
		}
	}

	protected override updateLabel(): void {
		if (this.options.label && this.label) {
			this.label.textContent = this.action.label;
		}
	}

	protected override getTooltip() {
		let title: string | null = null;

		if (this.action.tooltip) {
			title = this.action.tooltip;
		} else if (this.action.label) {
			title = this.action.label;

			if (this.options.keybinding) {
				title = nls.localize(
					{
						key: "titleLabel",
						comment: ["action title", "action keybinding"],
					},
					"{0} ({1})",
					title,
					this.options.keybinding,
				);
			}
		}
		return title ?? undefined;
	}

	protected override updateClass(): void {
		if (this.cssClass && this.label) {
			this.label.classList.remove(...this.cssClass.split(" "));
		}
		if (this.options.icon) {
			this.cssClass = this.getClass();

			if (this.label) {
				this.label.classList.add("codicon");

				if (this.cssClass) {
					this.label.classList.add(...this.cssClass.split(" "));
				}
			}

			this.updateEnabled();
		} else {
			this.label?.classList.remove("codicon");
		}
	}

	protected override updateEnabled(): void {
		if (this.action.enabled) {
			if (this.label) {
				this.label.removeAttribute("aria-disabled");
				this.label.classList.remove("disabled");
			}

			this.element?.classList.remove("disabled");
		} else {
			if (this.label) {
				this.label.setAttribute("aria-disabled", "true");
				this.label.classList.add("disabled");
			}

			this.element?.classList.add("disabled");
		}
	}

	protected override updateAriaLabel(): void {
		if (this.label) {
			const title = this.getTooltip() ?? "";
			this.label.setAttribute("aria-label", title);
		}
	}

	protected override updateChecked(): void {
		if (this.label) {
			if (this.action.checked !== undefined) {
				this.label.classList.toggle("checked", this.action.checked);

				if (this.options.isTabList) {
					this.label.setAttribute(
						"aria-selected",
						this.action.checked ? "true" : "false",
					);
				} else {
					this.label.setAttribute(
						"aria-checked",
						this.action.checked ? "true" : "false",
					);
					this.label.setAttribute("role", "checkbox");
				}
			} else {
				this.label.classList.remove("checked");
				this.label.removeAttribute(
					this.options.isTabList ? "aria-selected" : "aria-checked",
				);
				this.label.setAttribute("role", this.getDefaultAriaRole());
			}
		}
	}
}

export class SelectActionViewItem<T = string> extends BaseActionViewItem {
	protected selectBox: SelectBox;

	constructor(
		ctx: unknown,
		action: IAction,
		options: ISelectOptionItem[],
		selected: number,
		contextViewProvider: IContextViewProvider,
		styles: ISelectBoxStyles,
		selectBoxOptions?: ISelectBoxOptions,
	) {
		super(ctx, action);

		this.selectBox = new SelectBox(
			options,
			selected,
			contextViewProvider,
			styles,
			selectBoxOptions,
		);
		this.selectBox.setFocusable(false);

		this._register(this.selectBox);
		this.registerListeners();
	}

	setOptions(options: ISelectOptionItem[], selected?: number): void {
		this.selectBox.setOptions(options, selected);
	}

	select(index: number): void {
		this.selectBox.select(index);
	}

	private registerListeners(): void {
		this._register(
			this.selectBox.onDidSelect((e) =>
				this.runAction(e.selected, e.index),
			),
		);
	}

	protected runAction(option: string, index: number): void {
		this.actionRunner.run(
			this._action,
			this.getActionContext(option, index),
		);
	}

	protected getActionContext(option: string, index: number): T | string {
		return option;
	}

	override setFocusable(focusable: boolean): void {
		this.selectBox.setFocusable(focusable);
	}

	override focus(): void {
		this.selectBox?.focus();
	}

	override blur(): void {
		this.selectBox?.blur();
	}

	override render(container: HTMLElement): void {
		this.selectBox.render(container);
	}
}
