import {
	ActionRunner,
	IAction,
	IActionRunner,
	IRunEvent,
	Separator,
} from "../../../common/actions.js";
import { Emitter } from "../../../common/event.js";
import { KeyCode, KeyMod } from "../../../common/keyCodes.js";
import {
	Disposable,
	DisposableMap,
	DisposableStore,
	dispose,
	IDisposable,
} from "../../../common/lifecycle.js";
import * as types from "../../../common/types.js";
import * as DOM from "../../dom.js";
import { StandardKeyboardEvent } from "../../keyboardEvent.js";
import { IHoverDelegate } from "../hover/hoverDelegate.js";
import { createInstantHoverDelegate } from "../hover/hoverDelegateFactory.js";
import {
	ActionViewItem,
	BaseActionViewItem,
	IActionViewItemOptions,
} from "./actionViewItems.js";

import "./actionbar.css";

export interface IActionViewItem extends IDisposable {
	action: IAction;
	actionRunner: IActionRunner;

	setActionContext(context: unknown): void;
	render(element: HTMLElement): void;
	isEnabled(): boolean;
	focus(fromRight?: boolean): void; // TODO@isidorn what is this?
	blur(): void;
	showHover?(): void;
}
export interface IActionViewItemProvider {
	(
		action: IAction,
		options: IActionViewItemOptions,
	): IActionViewItem | undefined;
}
export const enum ActionsOrientation {
	HORIZONTAL,
	VERTICAL,
}
export interface ActionTrigger {
	keys?: KeyCode[];
	keyDown: boolean;
}
export interface IActionBarOptions {
	readonly orientation?: ActionsOrientation;
	readonly context?: unknown;
	readonly actionViewItemProvider?: IActionViewItemProvider;
	readonly actionRunner?: IActionRunner;
	readonly ariaLabel?: string;
	readonly ariaRole?: string;
	readonly triggerKeys?: ActionTrigger;
	readonly allowContextMenu?: boolean;
	readonly preventLoopNavigation?: boolean;
	readonly focusOnlyEnabledItems?: boolean;
	readonly hoverDelegate?: IHoverDelegate;
	/**
	 * If true, toggled primary items are highlighted with a background color.
	 * Some action bars exclusively use icon states, we don't want to enable this for them.
	 * Thus, this is opt-in.
	 */
	readonly highlightToggledItems?: boolean;
}
export interface IActionOptions extends IActionViewItemOptions {
	index?: number;
}
export class ActionBar extends Disposable implements IActionRunner {
	private readonly options: IActionBarOptions;
	private readonly _hoverDelegate: IHoverDelegate;
	private _actionRunner: IActionRunner;
	private readonly _actionRunnerDisposables = this._register(
		new DisposableStore(),
	);
	private _context: unknown;
	private readonly _orientation: ActionsOrientation;
	private readonly _triggerKeys: {
		keys: KeyCode[];
		keyDown: boolean;
	};
	// View Items
	viewItems: IActionViewItem[];
	private readonly viewItemDisposables = this._register(
		new DisposableMap<IActionViewItem>(),
	);
	private previouslyFocusedItem?: number;
	protected focusedItem?: number;
	private focusTracker: DOM.IFocusTracker;
	// Trigger Key Tracking
	private triggerKeyDown: boolean = false;
	private focusable: boolean = true;
	// Elements
	domNode: HTMLElement;
	protected readonly actionsList: HTMLElement;
	private readonly _onDidBlur = this._register(new Emitter<void>());
	readonly onDidBlur = this._onDidBlur.event;
	private readonly _onDidCancel = this._register(
		new Emitter<void>({
			onWillAddFirstListener: () => (this.cancelHasListener = true),
		}),
	);
	readonly onDidCancel = this._onDidCancel.event;
	private cancelHasListener = false;
	private readonly _onDidRun = this._register(new Emitter<IRunEvent>());
	readonly onDidRun = this._onDidRun.event;
	private readonly _onWillRun = this._register(new Emitter<IRunEvent>());
	readonly onWillRun = this._onWillRun.event;

	constructor(container: HTMLElement, options: IActionBarOptions = {}) {
		super();
		this.options = options;
		this._context = options.context ?? null;
		this._orientation =
			this.options.orientation ?? ActionsOrientation.HORIZONTAL;
		this._triggerKeys = {
			keyDown: this.options.triggerKeys?.keyDown ?? false,
			keys: this.options.triggerKeys?.keys ?? [
				KeyCode.Enter,
				KeyCode.Space,
			],
		};
		this._hoverDelegate =
