		switch (this.options.type) {
			case "error":
				typeLabel = nls.localize("dialogErrorMessage", "Error");

				break;

			case "warning":
				typeLabel = nls.localize("dialogWarningMessage", "Warning");

				break;

			case "pending":
				typeLabel = nls.localize("dialogPendingMessage", "In Progress");

				break;

			case "none":
			case "info":
			case "question":
			default:
