import { ActionRunner, IAction } from "../../../common/actions.js";
import { Emitter } from "../../../common/event.js";
import { KeyCode } from "../../../common/keyCodes.js";
import { IDisposable } from "../../../common/lifecycle.js";
import { IContextMenuProvider } from "../../contextmenu.js";
import {
	$,
	addDisposableListener,
	append,
	EventHelper,
	EventType,
	isMouseEvent,
} from "../../dom.js";
import { StandardKeyboardEvent } from "../../keyboardEvent.js";
import { Gesture, EventType as GestureEventType } from "../../touch.js";
import { AnchorAlignment } from "../contextview/contextview.js";
import type { IManagedHover } from "../hover/hover.js";
import { getBaseLayerHoverDelegate } from "../hover/hoverDelegate2.js";
import { getDefaultHoverDelegate } from "../hover/hoverDelegateFactory.js";
import { IMenuOptions } from "../menu/menu.js";

import "./dropdown.css";

export interface ILabelRenderer {
	(container: HTMLElement): IDisposable | null;
}
interface IBaseDropdownOptions {
	label?: string;
	labelRenderer?: ILabelRenderer;
}
class BaseDropdown extends ActionRunner {
	private _element: HTMLElement;
	private boxContainer?: HTMLElement;
	private _label?: HTMLElement;
	private contents?: HTMLElement;
	private visible: boolean | undefined;
	private _onDidChangeVisibility = this._register(new Emitter<boolean>());
	readonly onDidChangeVisibility = this._onDidChangeVisibility.event;
	private hover: IManagedHover | undefined;

	constructor(container: HTMLElement, options: IBaseDropdownOptions) {
		super();
		this._element = append(container, $(".monaco-dropdown"));
		this._label = append(this._element, $(".dropdown-label"));

		let labelRenderer = options.labelRenderer;

		if (!labelRenderer) {
			labelRenderer = (container: HTMLElement): IDisposable | null => {
				container.textContent = options.label || "";

				return null;
			};
		}
		for (const event of [
			EventType.CLICK,
			EventType.MOUSE_DOWN,
			GestureEventType.Tap,
		]) {
			this._register(
				addDisposableListener(this.element, event, (e) =>
					EventHelper.stop(e, true),
				),
			); // prevent default click behaviour to trigger
		}
		for (const event of [EventType.MOUSE_DOWN, GestureEventType.Tap]) {
			this._register(
				addDisposableListener(this._label, event, (e) => {
					if (isMouseEvent(e) && (e.detail > 1 || e.button !== 0)) {
						// prevent right click trigger to allow separate context menu (https://github.com/microsoft/vscode/issues/151064)
						// prevent multiple clicks to open multiple context menus (https://github.com/microsoft/vscode/issues/41363)
						return;
					}
					if (this.visible) {
						this.hide();
					} else {
						this.show();
					}
				}),
			);
		}
		this._register(
			addDisposableListener(this._label, EventType.KEY_UP, (e) => {
				const event = new StandardKeyboardEvent(e);

				if (
					event.equals(KeyCode.Enter) ||
					event.equals(KeyCode.Space)
				) {
					EventHelper.stop(e, true); // https://github.com/microsoft/vscode/issues/57997
					if (this.visible) {
						this.hide();
					} else {
						this.show();
					}
				}
			}),
		);

		const cleanupFn = labelRenderer(this._label);

		if (cleanupFn) {
			this._register(cleanupFn);
		}
		this._register(Gesture.addTarget(this._label));
	}
	get element(): HTMLElement {
		return this._element;
	}
	get label() {
		return this._label;
	}
	set tooltip(tooltip: string) {
		if (this._label) {
			if (!this.hover && tooltip !== "") {
				this.hover = this._register(
					getBaseLayerHoverDelegate().setupManagedHover(
						getDefaultHoverDelegate("mouse"),
						this._label,
						tooltip,
					),
				);
			} else if (this.hover) {
				this.hover.update(tooltip);
			}
		}
	}
	show(): void {
		if (!this.visible) {
			this.visible = true;
			this._onDidChangeVisibility.fire(true);
		}
	}
	hide(): void {
		if (this.visible) {
			this.visible = false;
			this._onDidChangeVisibility.fire(false);
		}
	}
	isVisible(): boolean {
