+{
+  "version": 3,
+  "sources": ["../../../../../../../../../../Dependency/Land/Dependency/Editor/Source/vs/base/browser/ui/findinput/findInput.ts"],
+  "sourcesContent": ["/*---------------------------------------------------------------------------------------------
 *  Copyright (c) Microsoft Corporation. All rights reserved.
 *  Licensed under the MIT License. See License.txt in the project root for license information.
 *--------------------------------------------------------------------------------------------*/

import { Emitter, Event } from "../../../common/event.js";
import { KeyCode } from "../../../common/keyCodes.js";
import * as dom from "../../dom.js";
import { IKeyboardEvent } from "../../keyboardEvent.js";
import { IMouseEvent } from "../../mouseEvent.js";
import { IContextViewProvider } from "../contextview/contextview.js";
import {
	HistoryInputBox,
	IInputBoxStyles,
	IInputValidator,
	IMessage as InputBoxMessage,
} from "../inputbox/inputBox.js";
import { IToggleStyles, Toggle } from "../toggle/toggle.js";
import { Widget } from "../widget.js";
import {
	CaseSensitiveToggle,
	RegexToggle,
	WholeWordsToggle,
} from "./findInputToggles.js";

import "./findInput.css";

import * as nls from "../../../../nls.js";
import { IHistory } from "../../../common/history.js";
import {
	DisposableStore,
	MutableDisposable,
} from "../../../common/lifecycle.js";
import { createInstantHoverDelegate } from "../hover/hoverDelegateFactory.js";

export interface IFindInputOptions {
	readonly placeholder?: string;
	readonly width?: number;
	readonly validation?: IInputValidator;
	readonly label: string;
	readonly flexibleHeight?: boolean;
	readonly flexibleWidth?: boolean;
	readonly flexibleMaxHeight?: number;

	readonly showCommonFindToggles?: boolean;
	readonly appendCaseSensitiveLabel?: string;
	readonly appendWholeWordsLabel?: string;
	readonly appendRegexLabel?: string;
	readonly additionalToggles?: Toggle[];
	readonly showHistoryHint?: () => boolean;
	readonly toggleStyles: IToggleStyles;
	readonly inputBoxStyles: IInputBoxStyles;
	readonly history?: IHistory<string>;
}

const NLS_DEFAULT_LABEL = nls.localize("defaultLabel", "input");

export class FindInput extends Widget {
	static readonly OPTION_CHANGE: string = "optionChange";

	private placeholder: string;
	private validation?: IInputValidator;
	private label: string;
	private readonly showCommonFindToggles: boolean;
	private fixFocusOnOptionClickEnabled = true;
	private imeSessionInProgress = false;
	private readonly additionalTogglesDisposables: MutableDisposable<DisposableStore> =
		this._register(new MutableDisposable());

	protected readonly controls: HTMLDivElement;
	protected readonly regex?: RegexToggle;
	protected readonly wholeWords?: WholeWordsToggle;
	protected readonly caseSensitive?: CaseSensitiveToggle;
	protected additionalToggles: Toggle[] = [];
	public readonly domNode: HTMLElement;
	public readonly inputBox: HistoryInputBox;

	private readonly _onDidOptionChange = this._register(
		new Emitter<boolean>(),
	);
	public readonly onDidOptionChange: Event<boolean /* via keyboard */> =
		this._onDidOptionChange.event;

	private readonly _onKeyDown = this._register(new Emitter<IKeyboardEvent>());
	public readonly onKeyDown: Event<IKeyboardEvent> = this._onKeyDown.event;

	private readonly _onMouseDown = this._register(new Emitter<IMouseEvent>());
	public readonly onMouseDown: Event<IMouseEvent> = this._onMouseDown.event;

	private readonly _onInput = this._register(new Emitter<void>());
	public readonly onInput: Event<void> = this._onInput.event;

	private readonly _onKeyUp = this._register(new Emitter<IKeyboardEvent>());
	public readonly onKeyUp: Event<IKeyboardEvent> = this._onKeyUp.event;

	private _onCaseSensitiveKeyDown = this._register(
		new Emitter<IKeyboardEvent>(),
	);
	public readonly onCaseSensitiveKeyDown: Event<IKeyboardEvent> =
		this._onCaseSensitiveKeyDown.event;

	private _onRegexKeyDown = this._register(new Emitter<IKeyboardEvent>());
	public readonly onRegexKeyDown: Event<IKeyboardEvent> =
		this._onRegexKeyDown.event;

	constructor(
		parent: HTMLElement | null,
		contextViewProvider: IContextViewProvider | undefined,
		options: IFindInputOptions,
	) {
		super();
		this.placeholder = options.placeholder || "";
		this.validation = options.validation;
		this.label = options.label || NLS_DEFAULT_LABEL;
		this.showCommonFindToggles = !!options.showCommonFindToggles;

		const appendCaseSensitiveLabel = options.appendCaseSensitiveLabel || "";

		const appendWholeWordsLabel = options.appendWholeWordsLabel || "";

		const appendRegexLabel = options.appendRegexLabel || "";

		const flexibleHeight = !!options.flexibleHeight;

		const flexibleWidth = !!options.flexibleWidth;

		const flexibleMaxHeight = options.flexibleMaxHeight;

		this.domNode = document.createElement("div");
		this.domNode.classList.add("monaco-findInput");

		this.inputBox = this._register(
			new HistoryInputBox(this.domNode, contextViewProvider, {
				placeholder: this.placeholder || "",
				ariaLabel: this.label || "",
				validationOptions: {
					validation: this.validation,
				},
				showHistoryHint: options.showHistoryHint,
				flexibleHeight,
				flexibleWidth,
				flexibleMaxHeight,
				inputBoxStyles: options.inputBoxStyles,
				history: options.history,
			}),
		);

		const hoverDelegate = this._register(createInstantHoverDelegate());

		if (this.showCommonFindToggles) {
			this.regex = this._register(
				new RegexToggle({
					appendTitle: appendRegexLabel,
					isChecked: false,
					hoverDelegate,
					...options.toggleStyles,
				}),
			);
			this._register(
				this.regex.onChange((viaKeyboard) => {
					this._onDidOptionChange.fire(viaKeyboard);

					if (!viaKeyboard && this.fixFocusOnOptionClickEnabled) {
						this.inputBox.focus();
					}
					this.validate();
				}),
			);
			this._register(
				this.regex.onKeyDown((e) => {
					this._onRegexKeyDown.fire(e);
				}),
			);

			this.wholeWords = this._register(
				new WholeWordsToggle({
					appendTitle: appendWholeWordsLabel,
					isChecked: false,
					hoverDelegate,
					...options.toggleStyles,
				}),
			);
			this._register(
				this.wholeWords.onChange((viaKeyboard) => {
					this._onDidOptionChange.fire(viaKeyboard);

					if (!viaKeyboard && this.fixFocusOnOptionClickEnabled) {
						this.inputBox.focus();
					}
					this.validate();
				}),
			);

			this.caseSensitive = this._register(
				new CaseSensitiveToggle({
					appendTitle: appendCaseSensitiveLabel,
					isChecked: false,
					hoverDelegate,
					...options.toggleStyles,
				}),
			);
			this._register(
				this.caseSensitive.onChange((viaKeyboard) => {
					this._onDidOptionChange.fire(viaKeyboard);

					if (!viaKeyboard && this.fixFocusOnOptionClickEnabled) {
						this.inputBox.focus();
					}
					this.validate();
				}),
			);
			this._register(
				this.caseSensitive.onKeyDown((e) => {
					this._onCaseSensitiveKeyDown.fire(e);
				}),
			);

			// Arrow-Key support to navigate between options
			const indexes = [
				this.caseSensitive.domNode,
				this.wholeWords.domNode,
				this.regex.domNode,
			];
			this.onkeydown(this.domNode, (event: IKeyboardEvent) => {
				if (
					event.equals(KeyCode.LeftArrow) ||
					event.equals(KeyCode.RightArrow) ||
					event.equals(KeyCode.Escape)
				) {
					const index = indexes.indexOf(
						<HTMLElement>this.domNode.ownerDocument.activeElement,
					);

					if (index >= 0) {
						let newIndex: number = -1;

						if (event.equals(KeyCode.RightArrow)) {
							newIndex = (index + 1) % indexes.length;
						} else if (event.equals(KeyCode.LeftArrow)) {
							if (index === 0) {
								newIndex = indexes.length - 1;
							} else {
								newIndex = index - 1;
							}
						}

						if (event.equals(KeyCode.Escape)) {
							indexes[index].blur();
							this.inputBox.focus();
						} else if (newIndex >= 0) {
							indexes[newIndex].focus();
						}

						dom.EventHelper.stop(event, true);
					}
				}
			});
		}

		this.controls = document.createElement("div");
		this.controls.className = "controls";
		this.controls.style.display = this.showCommonFindToggles ? "" : "none";

		if (this.caseSensitive) {
			this.controls.append(this.caseSensitive.domNode);
		}
		if (this.wholeWords) {
			this.controls.appendChild(this.wholeWords.domNode);
		}
		if (this.regex) {
			this.controls.appendChild(this.regex.domNode);
		}

		this.setAdditionalToggles(options?.additionalToggles);

		if (this.controls) {
			this.domNode.appendChild(this.controls);
		}

		parent?.appendChild(this.domNode);

		this._register(
			dom.addDisposableListener(
				this.inputBox.inputElement,
				"compositionstart",
				(e: CompositionEvent) => {
					this.imeSessionInProgress = true;
				},
			),
		);
		this._register(
			dom.addDisposableListener(
				this.inputBox.inputElement,
				"compositionend",
				(e: CompositionEvent) => {
					this.imeSessionInProgress = false;
					this._onInput.fire();
				},
			),
		);

		this.onkeydown(this.inputBox.inputElement, (e) =>
			this._onKeyDown.fire(e),
		);
		this.onkeyup(this.inputBox.inputElement, (e) => this._onKeyUp.fire(e));
		this.oninput(this.inputBox.inputElement, (e) => this._onInput.fire());
		this.onmousedown(this.inputBox.inputElement, (e) =>
			this._onMouseDown.fire(e),
		);
	}

	public get isImeSessionInProgress(): boolean {
		return this.imeSessionInProgress;
	}

	public get onDidChange(): Event<string> {
		return this.inputBox.onDidChange;
	}

	public layout(style: {
		collapsedFindWidget: boolean;
		narrowFindWidget: boolean;
		reducedFindWidget: boolean;
	}) {
		this.inputBox.layout();
		this.updateInputBoxPadding(style.collapsedFindWidget);
	}

	public enable(): void {
		this.domNode.classList.remove("disabled");
		this.inputBox.enable();
		this.regex?.enable();
		this.wholeWords?.enable();
		this.caseSensitive?.enable();

		for (const toggle of this.additionalToggles) {
			toggle.enable();
		}
	}

	public disable(): void {
		this.domNode.classList.add("disabled");
		this.inputBox.disable();
		this.regex?.disable();
		this.wholeWords?.disable();
		this.caseSensitive?.disable();

		for (const toggle of this.additionalToggles) {
			toggle.disable();
		}
	}

	public setFocusInputOnOptionClick(value: boolean): void {
		this.fixFocusOnOptionClickEnabled = value;
	}

	public setEnabled(enabled: boolean): void {
		if (enabled) {
			this.enable();
		} else {
			this.disable();
		}
	}

	public setAdditionalToggles(toggles: Toggle[] | undefined): void {
		for (const currentToggle of this.additionalToggles) {
			currentToggle.domNode.remove();
		}
		this.additionalToggles = [];
		this.additionalTogglesDisposables.value = new DisposableStore();

		for (const toggle of toggles ?? []) {
			this.additionalTogglesDisposables.value.add(toggle);
			this.controls.appendChild(toggle.domNode);

			this.additionalTogglesDisposables.value.add(
				toggle.onChange((viaKeyboard) => {
					this._onDidOptionChange.fire(viaKeyboard);

					if (!viaKeyboard && this.fixFocusOnOptionClickEnabled) {
						this.inputBox.focus();
					}
				}),
			);

			this.additionalToggles.push(toggle);
		}

		if (this.additionalToggles.length > 0) {
			this.controls.style.display = "";
		}

		this.updateInputBoxPadding();
	}

	private updateInputBoxPadding(controlsHidden = false) {
		if (controlsHidden) {
			this.inputBox.paddingRight = 0;
		} else {
			this.inputBox.paddingRight =
				(this.caseSensitive?.width() ?? 0) +
				(this.wholeWords?.width() ?? 0) +
				(this.regex?.width() ?? 0) +
				this.additionalToggles.reduce((r, t) => r + t.width(), 0);
		}
	}

	public clear(): void {
		this.clearValidation();
		this.setValue("");
		this.focus();
	}

	public getValue(): string {
		return this.inputBox.value;
	}

	public setValue(value: string): void {
		if (this.inputBox.value !== value) {
			this.inputBox.value = value;
		}
	}

	public onSearchSubmit(): void {
		this.inputBox.addToHistory();
	}

	public select(): void {
		this.inputBox.select();
	}

	public focus(): void {
		this.inputBox.focus();
	}

	public getCaseSensitive(): boolean {
		return this.caseSensitive?.checked ?? false;
	}

	public setCaseSensitive(value: boolean): void {
		if (this.caseSensitive) {
			this.caseSensitive.checked = value;
		}
	}

	public getWholeWords(): boolean {
		return this.wholeWords?.checked ?? false;
	}

	public setWholeWords(value: boolean): void {
		if (this.wholeWords) {
			this.wholeWords.checked = value;
		}
	}

	public getRegex(): boolean {
		return this.regex?.checked ?? false;
	}

	public setRegex(value: boolean): void {
		if (this.regex) {
			this.regex.checked = value;
			this.validate();
		}
	}

	public focusOnCaseSensitive(): void {
		this.caseSensitive?.focus();
	}

	public focusOnRegex(): void {
		this.regex?.focus();
	}

	private _lastHighlightFindOptions: number = 0;
	public highlightFindOptions(): void {
		this.domNode.classList.remove(
			"highlight-" + this._lastHighlightFindOptions,
		);
		this._lastHighlightFindOptions = 1 - this._lastHighlightFindOptions;
		this.domNode.classList.add(
			"highlight-" + this._lastHighlightFindOptions,
		);
	}

	public validate(): void {
		this.inputBox.validate();
	}

	public showMessage(message: InputBoxMessage): void {
		this.inputBox.showMessage(message);
	}

	public clearMessage(): void {
		this.inputBox.hideMessage();
	}

	private clearValidation(): void {
		this.inputBox.hideMessage();
	}
}
